"""土家语输入键盘（网页版）：Ye 拼音 + SIL IPA + 词库候选 + 语音。

自动生成，勿手改；生成器在 tujia-tts/space/gen_ipa_kb.py。
用法：
    txt = gr.Textbox(..., elem_id="ipa-input")
    gr.HTML(IPA_HTML)
    demo.load(None, None, None, js=IPA_JS)
"""

IPA_CSS = """#ipa-kb{margin-top:8px;user-select:none;width:100%;max-width:100%;overflow:hidden}
/* 覆盖 Gradio .prose button 的 margin-bottom（会让最后一个按钮错位） */
#ipa-kb button{margin:0;box-sizing:border-box;font-family:inherit}
#ipa-kb .kb-hintbar{font-size:12px;color:#777;margin-bottom:6px}
#ipa-kb .kb-tools{display:flex;gap:6px;margin-bottom:6px;flex-wrap:nowrap;align-items:center;height:42px;
  position:relative;width:100%;min-width:0}
#ipa-kb .kb-tools>button{flex:0 0 auto}
#ipa-kb .kb-tools button{height:30px;padding:0 9px;border:1px solid #d5d5d5;border-radius:15px;
  background:#fff;font-size:13px;color:#444;cursor:pointer;touch-action:manipulation}
#ipa-kb .kb-tools button.on{background:#2f7a67;border-color:#2f7a67;color:#fff}
#ipa-kb .kb-tools button.rec,#ipa-kb .kb-row button.rec{background:#c0392b;border-color:#c0392b;color:#fff}
/* 单词候选：与 Ye/IPA 同行单行滚动 */
#ipa-kb .kb-cands{display:flex;gap:3px;flex-wrap:nowrap;overflow-x:auto;overflow-y:hidden;
  height:36px;align-items:center;flex:1 1 0;width:0;min-width:0;max-width:100%;padding:0 4px;box-sizing:border-box;
  overscroll-behavior-x:contain;background:#eef6f3;border:1px solid #cfe3dc;border-radius:8px}
/* 长按候选：浮层多行平铺，不挤压布局也不滚动，点空白处收起 */
#ipa-kb .kb-alts{position:absolute;left:0;right:0;top:0;z-index:20;display:flex;flex-wrap:wrap;gap:3px;
  padding:4px;box-sizing:border-box;background:#eef6f3;border:1px solid #cfe3dc;border-radius:8px;
  overscroll-behavior-x:contain;box-shadow:0 6px 18px rgba(0,0,0,.14)}
#ipa-kb .kb-alts[hidden],#ipa-kb .kb-cands[hidden]{display:none}
#ipa-kb .kb-alts button{min-width:32px;height:30px;font-size:16px;flex:0 0 auto}
#ipa-kb .kb-cands button{height:30px;padding:0 5px;font-size:13px;display:flex;gap:4px;align-items:center;
  flex:0 0 auto;white-space:nowrap}
#ipa-kb .kb-cands button small{color:#888;font-size:10px}
#ipa-kb .kb-row{display:flex;gap:4px;margin-bottom:4px;width:100%;min-width:0}
#ipa-kb .kb-row button{flex:1 0 0;min-width:0;height:42px;padding:0 2px;border:1px solid #d5d5d5;
  border-radius:6px;background:#fff;color:#222;font-size:16px;line-height:1;cursor:pointer;
  touch-action:manipulation;position:relative;overflow:hidden}
#ipa-kb .kb-row button:active{background:#e8f3ef;border-color:#2f7a67}
#ipa-kb .kb-row button[data-kind="blank"]{background:transparent;border-color:transparent;pointer-events:none}
#ipa-kb .kb-row button[data-kind="layer"],#ipa-kb .kb-row button[data-kind="shift"]{font-size:12px;background:#f4f4f4}
#ipa-kb .kb-row button .kb-h{position:absolute;left:3px;top:1px;font-size:9px;color:#999}
#ipa-kb .kb-row button .kb-m{display:block;margin-top:5px}
#ipa-kb .kb-row button .kb-icon{display:flex;align-items:center;justify-content:center;margin-top:0;height:40px}
#ipa-kb .kb-status{font-size:12px;color:#b35309;margin-top:4px;min-height:16px}
"""

